<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
import { ChevronRight, History } from '@lucide/vue';
import EmptyState from '@/components/EmptyState.vue';
import PageHeader from '@/components/PageHeader.vue';
import { Badge } from '@/components/ui/badge';
import { period as periodRoute } from '@/routes/shopping-list';
import { index, show } from '@/routes/shopping-lists';

/**
 * Every shopping list of the household (RN-36): current periods, finished periods and the
 * weekly lists generated by closing a menu before 2026-10-21, kept with their lines,
 * purchases and receptions.
 */
defineProps<{
    lists: {
        id: number;
        label: string;
        kind: 'weekly' | 'period' | 'rolling';
        active: boolean;
        items: number;
        receptions: number;
    }[];
}>();

defineOptions({
    layout: {
        breadcrumbs: [
            { title: 'Lista de la compra', href: periodRoute() },
            { title: 'Historial', href: index() },
        ],
    },
});
</script>

<template>
    <Head title="Historial de listas" />

    <div class="mx-auto flex w-full max-w-3xl flex-col gap-6 p-4 sm:p-6">
        <PageHeader
            title="Historial de listas"
            description="Todas tus listas de la compra, con sus líneas, lo comprado y las compras registradas."
        />

        <EmptyState
            v-if="lists.length === 0"
            :icon="History"
            title="Aún no tienes listas."
        />

        <ul v-else class="grid gap-px overflow-hidden rounded-md bg-border">
            <li v-for="list in lists" :key="list.id">
                <Link
                    :href="show(list.id)"
                    class="flex items-center gap-3 bg-card px-4 py-3 hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset"
                >
                    <span class="grid min-w-0 flex-1 gap-1">
                        <span class="font-medium break-words">{{
                            list.label
                        }}</span>
                        <span
                            class="flex flex-wrap items-center gap-2 text-xs text-muted-foreground"
                        >
                            <Badge v-if="list.active" variant="info"
                                >Actual</Badge
                            >
                            <Badge
                                v-else-if="list.kind === 'weekly'"
                                variant="outline"
                                >Semanal (anterior)</Badge
                            >
                            <Badge v-else variant="outline">Terminada</Badge>
                            {{ list.items }}
                            {{ list.items === 1 ? 'línea' : 'líneas' }} ·
                            {{ list.receptions }}
                            {{
                                list.receptions === 1
                                    ? 'compra registrada'
                                    : 'compras registradas'
                            }}
                        </span>
                    </span>
                    <ChevronRight class="size-4 text-muted-foreground" />
                </Link>
            </li>
        </ul>
    </div>
</template>
